#pragma once

#include "Engine/Renderer/Renderer.h"

#include "VisualRules.h"

#include <string>

/// The textures the game draws with, loaded once at start-up (the Renderer owns them; these are just
/// handles). All artwork is original, generated by Game/assets/generate_assets.py.
struct GameAssets
{
	Engine::TextureId Ships[Astro::ShipVariantCount]; // ship_1..ship_4: blue, orange, green, magenta
	Engine::TextureId ReplayShip;                     // the translucent "ghost" ship shown during a replay
	Engine::TextureId Bullet;
	Engine::TextureId Explosion;                      // a horizontal strip of Astro::ExplosionFrameCount frames
	Engine::TextureId Wall;                           // a 32x32 tile, repeated over walls and obstacles
	Engine::TextureId Stars;                          // a 512x512 star tile, repeated over the background
};

/// Loads every PNG from `directory` (which must end in a path separator). Throws
/// std::runtime_error naming the missing file if one cannot be loaded.
GameAssets LoadGameAssets(Engine::Renderer& renderer, const std::string& directory);
